28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "membership_number")
81	    private String membershipNumber;
82	
83	    @Column(name = "bulk_signup_warning")
84	    private Boolean bulkSignupWarning;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "postcode")
90	    private String postcode;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
96	    private Set<Pet> pets;
97	
98	    public String getTitle() {
99	        return this.title;
100	    }
101	
102	    public void setTitle(String title) {
103	        this.title = title;
104	    }
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    /**
115	     * The first line of this owner's structured postal address, or {@code null} when the owner was
116	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
117	     * present; see {@link #getAddress()} for the composed form.
118	     */
119	    public String getAddressLine1() {
120	        return this.addressLine1;
121	    }
122	
123	    public void setAddressLine1(String addressLine1) {
124	        this.addressLine1 = addressLine1;
125	    }
126	
127	    /**
128	     * The optional second line of this owner's structured postal address, or {@code null} when none
129	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
130	     * composed {@link #getAddress() address}.
131	     */
132	    public String getAddressLine2() {
133	        return this.addressLine2;
134	    }
135	
136	    public void setAddressLine2(String addressLine2) {
137	        this.addressLine2 = addressLine2;
138	    }
139	
140	    public String getCity() {
141	        return this.city;
142	    }
143	
144	    public void setCity(String city) {
145	        this.city = city;
146	    }
147	
148	    public String getTelephone() {
149	        return this.telephone;
150	    }
151	
152	    public void setTelephone(String telephone) {
153	        this.telephone = telephone;
154	    }
155	
156	    /**
157	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
158	     * as the calling code, a space, then the national digits grouped in threes, e.g.
159	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
160	     */
161	    @Transient
162	    public String getTelephoneDisplay() {
163	        return TelephoneFormatter.toDisplay(this.telephone);
164	    }
165	
166	    public String getEmail() {
167	        return this.email;
168	    }
169	
170	    public void setEmail(String email) {
171	        this.email = email;
172	    }
173	
174	    public LocalDate getRegistrationDate() {
175	        return this.registrationDate;
176	    }
177	
178	    public void setRegistrationDate(LocalDate registrationDate) {
179	        this.registrationDate = registrationDate;
180	    }
181	
182	    public LocalDate getBirthDate() {
183	        return this.birthDate;
184	    }
185	
186	    public void setBirthDate(LocalDate birthDate) {
187	        this.birthDate = birthDate;
188	    }
189	
190	    public String getCustomerCode() {
191	        return this.customerCode;
192	    }
193	
194	    public void setCustomerCode(String customerCode) {
195	        this.customerCode = customerCode;
196	    }
197	
198	    public String getHouseholdId() {
199	        return this.householdId;
200	    }
201	
202	    public void setHouseholdId(String householdId) {
203	        this.householdId = householdId;
204	    }
205	
206	    public Integer getNamesakeCount() {
207	        return this.namesakeCount;
208	    }
209	
210	    public void setNamesakeCount(Integer namesakeCount) {
211	        this.namesakeCount = namesakeCount;
212	    }
213	
214	    public String getMembershipNumber() {
215	        return this.membershipNumber;
216	    }
217	
218	    public void setMembershipNumber(String membershipNumber) {
219	        this.membershipNumber = membershipNumber;
220	    }
221	
222	    /**
223	     * Whether this owner was created after more than 80 owners had already been registered on the
224	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
225	     */
226	    public Boolean getBulkSignupWarning() {
227	        return this.bulkSignupWarning;
228	    }
229	
230	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
231	        this.bulkSignupWarning = bulkSignupWarning;
232	    }
233	
234	    /**
235	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
236	     * counting this owner) captured once at creation.
237	     */
238	    public Integer getHouseholdSize() {
239	        return this.householdSize;
240	    }
241	
242	    public void setHouseholdSize(Integer householdSize) {
243	        this.householdSize = householdSize;
244	    }
245	
246	    /**
247	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
248	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
249	     */
250	    public String getPostcode() {
251	        return this.postcode;
252	    }
253	
254	    public void setPostcode(String postcode) {
255	        this.postcode = postcode;
256	    }
257	
258	    /**
259	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
260	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
261	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
262	     * and a declared member is not a suspected duplicate — this is not populated at creation.
263	     * Captured once at creation.
264	     */
265	    public Integer getPossibleDuplicateOf() {
266	        return this.possibleDuplicateOf;
267	    }
268	
269	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
270	        this.possibleDuplicateOf = possibleDuplicateOf;
271	    }
272	
273	    /**
274	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
275	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
276	     */
277	    @Transient
278	    public Boolean getPossibleDuplicate() {
279	        return this.possibleDuplicateOf != null;
280	    }
281	
282	    /**
283	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
284	     */
285	    @Transient
286	    public String getDisplayName() {
287	        return this.getLastName() + ", " + this.getFirstName();
288	    }
289	
290	    /**
291	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
292	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
293	     */
294	    @Transient
295	    public String getSalutation() {
296	        return (this.title == null || this.title.isBlank())
297	            ? this.getLastName()
298	            : this.title + " " + this.getLastName();
299	    }
300	
301	    /**
302	     * Return this owner's initials as the upper-cased first letters of the first and last
303	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
304	     */
305	    @Transient
306	    public String getInitials() {
307	        return initial(this.getFirstName()) + initial(this.getLastName());
308	    }
309	
310	    private static String initial(String name) {
311	        return Character.toUpperCase(name.charAt(0)) + ".";
312	    }
313	
314	    /** Points awarded when an email address is present. */
315	    private static final int EMAIL_POINTS = 2;
316	
317	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
318	    private static final int NO_NAMESAKE_POINTS = 1;
319	
320	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
321	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
322	
323	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
324	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
325	
326	    /** Points awarded for qualifying tenure. */
327	    private static final int TENURE_POINTS = 3;
328	
329	    /** The tenure, in days, that must be exceeded to earn {@link #TENURE_POINTS}. */
330	    private static final long MEMBERSHIP_TENURE_THRESHOLD_DAYS = 365;
331	
332	    /**
333	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
334	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
335	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
336	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
337	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days since registration).
338	     */
339	    @Transient
340	    public Integer getMembershipPoints() {
341	        int points = 0;
342	        if (hasEmail()) {
343	            points += EMAIL_POINTS;
344	        }
345	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
346	            points += NO_NAMESAKE_POINTS;
347	        }
348	        if (hasLargeHousehold()) {
349	            points += LARGE_HOUSEHOLD_POINTS;
350	        }
351	        if (hasQualifyingTenure()) {
352	            points += TENURE_POINTS;
353	        }
354	        return points;
355	    }
356	
357	    /**
358	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
359	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
360	     */
361	    @Transient
362	    public Integer getMembershipLevel() {
363	        int points = getMembershipPoints();
364	        if (points <= 1) {
365	            return 1;
366	        }
367	        if (points <= 3) {
368	            return 2;
369	        }
370	        if (points <= 5) {
371	            return 3;
372	        }
373	        return 4;
374	    }
375	
376	    /**
377	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
378	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
379	     * qualify.
380	     */
381	    private boolean hasLargeHousehold() {
382	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
383	    }
384	
385	    /**
386	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days, i.e.
387	     * more than that many days have elapsed since the {@code registrationDate}. Owners without a
388	     * registration date have no measurable tenure and do not qualify.
389	     */
390	    private boolean hasQualifyingTenure() {
391	        if (this.registrationDate == null) {
392	            return false;
393	        }
394	        long tenureDays = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
395	        return tenureDays > MEMBERSHIP_TENURE_THRESHOLD_DAYS;
396	    }
397	
398	    /** Whether this owner has a usable email address (present and not blank). */
399	    private boolean hasEmail() {
400	        return this.email != null && !this.email.isBlank();
401	    }
402	
403	    /**
404	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
405	     * present, otherwise {@code "PHONE"}.
406	     */
407	    @Transient
408	    public String getContactPreference() {
409	        return hasEmail() ? "EMAIL" : "PHONE";
410	    }
411	
412	    /**
413	     * Return this owner's age band derived from the {@code birthDate} as of the
414	     * {@code registrationDate}, or {@code null} when no birth date is known.
415	     */
416	    @Transient
417	    public AgeBand getAgeBand() {
418	        if (this.birthDate == null || this.registrationDate == null) {
419	            return null;
420	        }
421	        return AgeBand.asOf(this.birthDate, this.registrationDate);
422	    }
423	
424	    /**
425	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
426	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
427	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
428	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
429	     * region is resolved directly from the postcode and city.
430	     */
431	    @Transient
432	    public String getLocality() {
433	        if (this.customerCode == null) {
434	            return LocalityResolver.regionFor(this.postcode, this.city);
435	        }
436	        int separator = this.customerCode.indexOf('-');
437	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
438	    }
439	
440	    /**
441	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
442	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
443	     * known timezone.
444	     */
445	    @Transient
446	    public String getTimezone() {
447	        return LocalityResolver.timezoneFor(getLocality());
448	    }
449	
450	    /**
451	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
452	     * {@code customerCode}.
453	     */
454	    @Transient
455	    public Integer getCheckDigit() {
456	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
457	    }
458	
459	    /**
460	     * Return this owner's identity key, the single derived value all duplicate detection is based
461	     * on: the normalized telephone, email and household id joined with {@code '|'} as
462	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
463	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
464	     * because the telephone is part of the key, members of one household (same {@code householdId})
465	     * with different telephones have distinct keys and are not duplicates.
466	     */
467	    @Transient
468	    public String getIdentityKey() {
469	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
470	    }
471	
472	    private static String keyPart(String value) {
473	        return value == null ? "" : value;
474	    }
475	
476	    protected Set<Pet> getPetsInternal() {
477	        if (this.pets == null) {
478	            this.pets = new HashSet<>();
479	        }
480	        return this.pets;
481	    }
482	
483	    protected void setPetsInternal(Set<Pet> pets) {
484	        this.pets = pets;
485	    }
486	
487	    public List<Pet> getPets() {
488	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
489	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
490	        return Collections.unmodifiableList(sortedPets);
491	    }
492	
493	    public void setPets(List<Pet> pets) {
494	        this.pets = new HashSet<>(pets);
495	    }
496	
497	    public void addPet(Pet pet) {
498	        getPetsInternal().add(pet);
499	        pet.setOwner(this);
500	    }
501	
502	    /**
503	     * Return the Pet with the given name, or null if none found for this Owner.
504	     *
505	     * @param name to test
506	     * @return true if pet name is already in use
507	     */
508	    public Pet getPet(String name) {
509	        return getPet(name, false);
510	    }
511	
512	    /**
513	     * Return the Pet with the given name, or null if none found for this Owner.
514	     *
515	     * @param name to test
516	     * @return true if pet name is already in use
517	     */
518	    public Pet getPet(String name, boolean ignoreNew) {
519	        name = name.toLowerCase();
520	        for (Pet pet : getPetsInternal()) {
521	            if (!ignoreNew || !pet.isNew()) {
522	                String compName = pet.getName();
523	                compName = compName.toLowerCase();
524	                if (compName.equals(name)) {
525	                    return pet;
526	                }
527	            }
528	        }
529	        return null;
530	    }
531	
532	    public Pet getPet(Integer petId) {
533	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
534	    }
535	
536	    @Override
537	    public String toString() {
538	        return new ToStringCreator(this)
539	
540	            .append("id", this.getId())
541	            .append("new", this.isNew())
542	            .append("lastName", this.getLastName())
543	            .append("firstName", this.getFirstName())
544	            .append("address", this.address)
545	            .append("city", this.city)
546	            .append("telephone", this.telephone)
547	            .append("email", this.email)
548	            .append("registrationDate", this.registrationDate)
549	            .toString();
550	    }
551	}
