30	import org.springframework.samples.petclinic.rest.controller.BusinessDayResolver;
31	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerIdentityException;
33	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
34	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
35	import org.springframework.samples.petclinic.rest.controller.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
37	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.PostcodeValidator;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.samples.petclinic.service.HouseholdIdGenerator;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final PostcodeValidator postcodeValidator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final BusinessDayResolver businessDayResolver;
89	
90	    private final OwnerAuditLogger ownerAuditLogger;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    /** Maximum number of owners a single city may hold before further creations are rejected. */
95	    static final long MAX_OWNERS_PER_CITY = 50;
96	
97	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
98	    static final long MAX_OWNERS_PER_DAY = 100;
99	
100	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
101	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    public OwnerRestControllerV1(ClinicService clinicService,
104	                                 OwnerMapper ownerMapper,
105	                                 PetMapper petMapper,
106	                                 VisitMapper visitMapper,
107	                                 OwnerFieldsValidator ownerFieldsValidator,
108	                                 PostcodeValidator postcodeValidator,
109	                                 TelephoneNormalizer telephoneNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 AddressNormalizer addressNormalizer,
112	                                 BusinessDayResolver businessDayResolver,
113	                                 OwnerAuditLogger ownerAuditLogger,
114	                                 HouseholdIdGenerator householdIdGenerator) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	        this.ownerFieldsValidator = ownerFieldsValidator;
120	        this.postcodeValidator = postcodeValidator;
121	        this.telephoneNormalizer = telephoneNormalizer;
122	        this.emailNormalizer = emailNormalizer;
123	        this.addressNormalizer = addressNormalizer;
124	        this.businessDayResolver = businessDayResolver;
125	        this.ownerAuditLogger = ownerAuditLogger;
126	        this.householdIdGenerator = householdIdGenerator;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
132	        Collection<Owner> owners;
133	        if (lastName != null) {
134	            owners = this.clinicService.findOwnerByLastName(lastName);
135	        } else {
136	            owners = this.clinicService.findAllOwners();
137	        }
138	        if (owners.isEmpty()) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        this.normalizeAddress(ownerFieldsDto);
158	        this.ownerFieldsValidator.validate(ownerFieldsDto);
159	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
160	        HttpHeaders headers = new HttpHeaders();
161	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
162	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
163	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
164	        LocalDate serverDate = LocalDate.now();
165	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
166	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
167	        }
168	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
169	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
170	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
171	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
172	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
173	        }
174	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
175	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
176	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
177	        }
178	        if (owner.getPostcode() != null) {
179	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
180	        }
181	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
182	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
183	        }
184	        Owner householdDuplicate = this.clinicService.findHouseholdDuplicateOf(owner);
185	        if (householdDuplicate != null && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
186	            throw new DuplicateHouseholdException(owner.getHouseholdId());
187	        }
188	        this.clinicService.saveOwner(owner);
189	        this.ownerAuditLogger.logCreated(owner);
190	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
191	        headers.setLocation(UriComponentsBuilder.newInstance()
192	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
193	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    /**
197	     * Canonicalize the request's address fields in place, preferring the structured form. When a
198	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
199	     * normalized and the composed value stored on {@code address}; otherwise only the flat
200	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
201	     * value everything downstream reads.
202	     */
203	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
204	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
205	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
206	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
207	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
208	            ownerFieldsDto.setAddress(
209	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
210	        }
211	        else {
212	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
213	        }
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
219	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
220	        if (currentOwner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        currentOwner.setAddress(ownerFieldsDto.getAddress());
224	        currentOwner.setCity(ownerFieldsDto.getCity());
225	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
226	        currentOwner.setLastName(ownerFieldsDto.getLastName());
227	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
228	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
229	        this.clinicService.saveOwner(currentOwner);
230	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Transactional
235	    @Override
236	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        this.clinicService.deleteOwner(owner);
242	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        HttpHeaders headers = new HttpHeaders();
253	        Pet pet = petMapper.toPet(petFieldsDto);
254	        owner.setId(ownerId);
255	        pet.setOwner(owner);
256	        pet.getType().setName(null);
257	        this.clinicService.savePet(pet);
258	        PetDto petDto = petMapper.toPetDto(pet);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
260	            .buildAndExpand(pet.getId()).toUri());
261	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
