265	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
266	     * size at creation time.
267	     */
268	    private int countHouseholdMembers(Owner owner) {
269	        String householdId = owner.getHouseholdId();
270	        if (householdId == null) {
271	            return 1;
272	        }
273	        long existing = ownerRepository.findAll().stream()
274	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
275	            .count();
276	        return (int) (existing + 1);
