316	     * append {@code -<n>} using the smallest {@code n} of 2 or more that makes it unique. Used to
317	     * guarantee that distinct owners always receive distinct customer codes at creation time.
318	     */
319	    private String deduplicateCustomerCode(String customerCode) {
320	        Set<String> existing = ownerRepository.findAll().stream()
321	            .map(Owner::getCustomerCode)
322	            .filter(code -> code != null)
323	            .collect(Collectors.toSet());
324	        if (!existing.contains(customerCode)) {
325	            return customerCode;
326	        }
327	        int suffix = 2;
328	        while (existing.contains(customerCode + "-" + suffix)) {
329	            suffix++;
330	        }
331	        return customerCode + "-" + suffix;
